import re

from app.models import Site

_DOMAIN_RE = re.compile(
    r"^[a-zA-Z0-9]([a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?"
    r"(\.[a-zA-Z0-9]([a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?)*$"
)

# Rendered once — every stage domain proxies to the same wp_port/pma_port, so
# a shared upstream avoids duplicate-named upstream blocks when 2+ stages
# have a domain bound.
_UPSTREAMS = """\
# nginx config for site: {site_id}
# Generated by EZWeb — copy to /etc/nginx/sites-available/{site_id}.conf
# then: ln -s /etc/nginx/sites-available/{site_id}.conf /etc/nginx/sites-enabled/
# and:  nginx -s reload

upstream {site_id}_wp {{
    server 127.0.0.1:{wp_port};
}}
upstream {site_id}_pma {{
    server 127.0.0.1:{pma_port};
}}
"""

# Rendered once per bound stage domain.
_SERVER_BLOCK = """\
# {stage}
server {{
    listen 80;
    server_name {domain};

    client_max_body_size 2048M;

    location / {{
        proxy_pass         http://{site_id}_wp;
        proxy_set_header   Host              $host;
        proxy_set_header   X-Real-IP         $remote_addr;
        proxy_set_header   X-Forwarded-For   $proxy_add_x_forwarded_for;
        proxy_set_header   X-Forwarded-Proto $scheme;
        proxy_read_timeout 120s;
    }}
}}

# PhpMyAdmin — accessible at pma.{domain}
server {{
    listen 80;
    server_name pma.{domain};

    location / {{
        proxy_pass       http://{site_id}_pma;
        proxy_set_header Host            $host;
        proxy_set_header X-Real-IP       $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
    }}
}}

# To enable HTTPS run:
#   certbot --nginx -d {domain} -d pma.{domain}
"""


def generate(site: Site) -> str:
    stage_domains = [
        ("develop", site.domain_develop),
        ("qa", site.domain_qa),
        ("prod", site.domain_prod),
    ]

    blocks = []
    for stage, domain in stage_domains:
        if not domain:
            continue
        # Defense in depth: service.prepare_site() already validates new
        # domains, but this also guards sites created before that check
        # existed. The value is interpolated directly into an nginx config
        # file, so a malformed domain (e.g. containing newlines or braces)
        # could inject config directives.
        if not _DOMAIN_RE.match(domain):
            raise ValueError(f"[{stage}] 域名格式不正確，拒絕產生 nginx config：{domain}")
        blocks.append(_SERVER_BLOCK.format(stage=stage, site_id=site.id, domain=domain))

    if not blocks:
        raise ValueError("此站台尚未綁定任何 domain")

    header = _UPSTREAMS.format(site_id=site.id, wp_port=site.wp_port, pma_port=site.pma_port)
    return header + "\n" + "\n".join(blocks)
